create table public.contrato_versoes (id uuid,contrato_id uuid,versao integer,conteudo text,status text,created_at timestamp with time zone);
create table public.contratos (id uuid,reserva_id uuid,numero_contrato text,status text,observacoes text,pdf_url text,created_at timestamp with time zone,public_token uuid,assinado_em timestamp with time zone,assinado_por text,assinatura_documento text,assinatura_ip_hash text,assinatura_user_agent text,assinatura_aceite boolean,email_enviado_em timestamp with time zone,email_destino text,email_erro text);
create table public.estoque_itens (id uuid,codigo text,nome text,categoria text,cor text,quantidade_total integer,quantidade_manutencao integer,valor_reposicao numeric,fornecedor text,foto_url text,status text,observacoes text,created_at timestamp with time zone,updated_at timestamp with time zone,quantidade_disponivel integer,localizacao text,valor_locacao numeric(12,2));
create table public.kit_composicao (id uuid,kit_id uuid,item_id uuid,quantidade integer,observacoes text,created_at timestamp with time zone,valor_ajuste numeric(12,2));
create table public.kits (id uuid,codigo text,nome text,tema text,categoria text,quantidade integer,valor numeric,valor_fim_semana numeric,foto_url text,descricao text,observacoes text,status text,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.lancamentos_financeiros (id uuid,reserva_id uuid,tipo text,descricao text,categoria text,valor numeric,data_vencimento date,data_pagamento date,forma_pagamento text,status text,observacoes text,created_at timestamp with time zone,provedor_pagamento text,provedor_preferencia_id text,provedor_pagamento_id text,link_pagamento text,status_provedor text,status_detalhe_provedor text,provedor_atualizado_em timestamp with time zone);
create table public.oportunidades (id uuid,numero bigint,empresa_id uuid,cliente_id uuid,nome_contato text,celular text,email text,origem text,interesse text,data_evento date,quantidade_convidados integer,valor_estimado numeric(12,2),etapa text,proximo_contato date,motivo_perda text,observacoes text,responsavel_id uuid,created_by uuid,created_at timestamp with time zone,updated_at timestamp with time zone,origem_externa_id text,recebida_em timestamp with time zone,versao integer,cadastro_completo_em timestamp with time zone,desconto_tipo text,desconto_valor numeric(12,2),desconto_calculado numeric(12,2));
create table public.orcamento_itens (id uuid,orcamento_id uuid,kit_id uuid,descricao text,quantidade numeric(10,2),valor_unitario numeric(12,2),subtotal numeric(12,2) generated always as ((quantidade * valor_unitario)) stored,created_at timestamp with time zone,estoque_item_id uuid,item_conceitual_id uuid,tipo_origem text,preco_base numeric(12,2),preco_unitario_orcamento numeric(12,2),desconto numeric(12,2),observacao text,ordem integer,updated_at timestamp with time zone,subtotal_negociado numeric(12,2) generated always as (GREATEST(((quantidade * preco_unitario_orcamento) - desconto), (0)::numeric)) stored);
create table public.orcamento_taxas (id uuid,empresa_id uuid,orcamento_id uuid,descricao text,valor numeric(12,2),tipo text,observacao text,ordem integer,created_by uuid,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.orcamentos (id uuid,numero bigint,empresa_id uuid,oportunidade_id uuid,cliente_id uuid,status text,validade date,data_evento date,horario_evento text,data_retirada date,data_devolucao date,endereco_evento text,subtotal numeric(12,2),desconto numeric(12,2),acrescimos numeric(12,2),frete numeric(12,2),total numeric(12,2),observacoes text,created_by uuid,created_at timestamp with time zone,updated_at timestamp with time zone,reserva_id uuid,public_token uuid,resposta_cliente text,respondido_por text,respondido_em timestamp with time zone,resposta_observacao text,formalizacao_status text,contrato_id uuid,lancamento_sinal_id uuid,valor_sinal_formalizacao numeric(12,2),vencimento_sinal date,formalizado_em timestamp with time zone,contrato_assinado_em timestamp with time zone,sinal_pago_em timestamp with time zone,dados_cliente_completos_em timestamp with time zone,versao integer,email_enviado_em timestamp with time zone,email_destino text,email_erro text,hold_expira_em timestamp with time zone,formalizacao_bloqueio text,horario_retirada time without time zone,origem text,contato_nome text,contato_telefone text,contato_email text,tema_evento text,desconto_tipo text,desconto_valor numeric(12,2),total_taxas numeric(12,2),origem_externa_id text,status_antes_envio text);
create table public.recebimentos (id uuid,reserva_id uuid,valor numeric,data_recebimento date,forma_pagamento text,status text,observacoes text,created_at timestamp with time zone,lancamento_id uuid);
create table public.reserva_itens (id uuid,reserva_id uuid,kit_id uuid,descricao text,quantidade numeric(10,2),valor_unitario numeric(12,2),subtotal numeric(12,2) generated always as ((quantidade * valor_unitario)) stored,ordem integer,created_at timestamp with time zone,kit_composicao_id uuid,estoque_item_id uuid);
create table public.reservas (id uuid,cliente_id uuid,kit_id uuid,data_evento date,horario_evento text,endereco_evento text,valor_total numeric,valor_sinal numeric,status text,observacoes text,created_at timestamp with time zone,status_pagamento text,data_pagamento_sinal date,data_pagamento_final date,forma_pagamento_sinal text,forma_pagamento_final text,data_festa date,data_retirada date,data_devolucao date,status_comercial text,status_operacional text,orcamento_id uuid,horario_retirada time without time zone);
create table public.usuarios_empresa (id uuid,usuario_id uuid,empresa_id uuid,nome text,perfil text,ativo boolean,created_at timestamp with time zone,updated_at timestamp with time zone,updated_by uuid);
create role anon;create role authenticated;create role service_role;
create schema auth;
create function auth.uid() returns uuid language sql as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function public.verificar_disponibilidade_orcamento_confirmacao(uuid,uuid) returns jsonb language sql as $$select '{"disponivel":true}'::jsonb$$;
alter table public.contrato_versoes alter column id set default gen_random_uuid();
alter table public.contratos alter column id set default gen_random_uuid();
alter table public.estoque_itens alter column id set default gen_random_uuid();
alter table public.kit_composicao alter column id set default gen_random_uuid();
alter table public.kits alter column id set default gen_random_uuid();
alter table public.lancamentos_financeiros alter column id set default gen_random_uuid();
alter table public.oportunidades alter column id set default gen_random_uuid();
alter table public.orcamento_itens alter column id set default gen_random_uuid();
alter table public.orcamento_taxas alter column id set default gen_random_uuid();
alter table public.orcamentos alter column id set default gen_random_uuid();
alter table public.recebimentos alter column id set default gen_random_uuid();
alter table public.reserva_itens alter column id set default gen_random_uuid();
alter table public.reservas alter column id set default gen_random_uuid();
alter table public.usuarios_empresa alter column id set default gen_random_uuid();
alter table public.orcamentos alter column numero set default 123;
alter table public.reservas alter column created_at set default now();
alter table public.contratos alter column created_at set default now();
alter table public.contratos alter column public_token set default gen_random_uuid();
alter table public.lancamentos_financeiros alter column created_at set default now();
create unique index on public.recebimentos(lancamento_id) where lancamento_id is not null;


create table public.clientes(id uuid, email text);
